PEOPLE_DISCOVERIES.forEach(([name,born,died,country,work,impact,url],i)=>{const other=PEOPLE_DISCOVERIES.filter((_,n)=>n!==i),source={url,label:'Learn about '+name,checked:'11 November 2026'},bio=`${name} (${born}–${died}) was born in ${country}. ${work}. ${impact}`;discoveryQuestion('famouspeople',`What is ${name} best known for?`,work,other.map(p=>p[4]),bio,1,source,name);discoveryQuestion('famouspeople',`Where was ${name} born?`,country,other.map(p=>p[3]),bio,1,source,name);discoveryQuestion('famouspeople',`Which years show ${name}'s birth and death?`,`${born}–${died}`,other.map(p=>`${p[1]}–${p[2]}`),bio,2,source,name);discoveryQuestion('famouspeople',`Which statement explains ${name}'s contribution to people's lives?`,impact,other.map(p=>p[5]),bio,3,source,name);discoveryQuestion('famouspeople',`Who fits this description: ${work.toLowerCase()}?`,name,other.map(p=>p[0]),bio,2,source,name);discoveryQuestion('famouspeople',`${name} lived from ${born} to ${died}. What does the first date mean?`,'Year of birth',['Year of death','Year every invention was completed','Year a country was founded'],`A lifespan written ${born}–${died} gives birth year first and death year second. ${impact}`,1,source,name)});
